    public static void TestEveryFixtureDumpIsItsGolden() {
        // Row: file, password, golden. The dump of the file, read in memory, is the golden's
        // bytes (less its line feed): annotations, fields, signatures, outlines, labels,
        // metadata, named destinations, all four targets.
        byte[] f = emon.Testport.TestFile("pdf/catalog.txt");
        int n = emon.Port.BlobLen(f);
        int pos = 0;
        int line = 0;
        int rows = 0;
        int e = 0;
        int s0 = 0;
        int s1 = 0;
        while (pos < n) {
            line += 1;
            e = CgNl(f, pos);
            if ((pos < e) && (emon.Port.BlobU8(f, pos) != 35)) {
                rows += 1;
                s0 = CgTab(f, pos, e);
                s1 = CgTab(f, s0 + 1, e);
                System.Text.StringBuilder t = emon.Testport.NewText();
                byte[] g = emon.Testport.TestFileSpan(f, s1 + 1, e);
                emon.Testport.AssertEqAt(CgDump(emon.Port.SrcOfBlob(emon.Testport.TestFileSpan(f, pos, s0)), t), 0, "opened and read", line);
                emon.Testport.AssertTextSpan(t, g, 0, emon.Port.BlobLen(g) - 1, "the golden", line);
            }
            pos = e + 1;
        }
        emon.Testport.AssertThat(rows >= 12, "the fixtures were read");
    }
