            if (emon.Port.CellsAt(md, 0) >= 0) {
                while (k < emon.Port.CellsAt(md, 1)) {
                    h = CgFold(h, emon.Port.CellsAt(txt, emon.Port.CellsAt(md, 0) + k));
                    k += 1;
                }
            }
            emon.Port.TextAscii(t, ",");
            emon.Port.TextI32(t, h);
        }
        return 0;
    }
