    internal static int CgSurvive(emon.Port.Src pdf) {
        // Read everything from a file that may be damaged: none of it may fault. Answers the
        // verdict of `cg-dump`.
        System.Text.StringBuilder t = emon.Testport.NewText();
        return CgDump(pdf, t);
    }
    internal static int CgCut(byte[] f, int n, emon.Port.Cells cut) {
        // cut = the first n bytes of f.
        int i = 0;
        emon.Port.CellsDrop(cut, 0);
        while (i < n) {
            emon.Port.CellsPush(cut, emon.Port.BlobU8(f, i));
            i += 1;
        }
        return n;
    }
    internal static int CgTruncations(byte[] f, int step, emon.Port.Cells cut) {
        // Every truncation of f, every `step` bytes: none may fault. Answers how many still read.
        int n = emon.Port.BlobLen(f);
        int k = 0;
        int ok = 0;
        while (k <= n) {
            CgCut(f, k, cut);
            if (CgSurvive(emon.Port.SrcOfBlob(emon.Testport.CellsBlob(cut))) == 0) {
                ok += 1;
            }
            k += step;
        }
        return ok;
    }
    internal static int CgCorruptions(byte[] f, int rounds, int flips, int seed, emon.Port.Cells cut, emon.Port.Cells rng) {
        // `rounds` copies of f with `flips` random bytes replaced (SplitMix, so every target
        // damages the same bytes): none may fault. Answers how many still read.
        int n = emon.Port.BlobLen(f);
        int r = 0;
        int j = 0;
        int at = 0;
        int ok = 0;
        Splitmix.SmSeed(rng, (long) seed);
        while (r < rounds) {
            CgCut(f, n, cut);
            j = 0;
            while (j < flips) {
                at = Splitmix.SmBelow(rng, n);
                emon.Port.CellsSet(cut, at, Splitmix.SmBelow(rng, 256));
                j += 1;
            }
            if (CgSurvive(emon.Port.SrcOfBlob(emon.Testport.CellsBlob(cut))) == 0) {
                ok += 1;
            }
            r += 1;
        }
        return ok;
    }
    [Xunit.Fact]
    public static void TestNoTruncationOfAFixtureFaults() {
        // Every 11th cut of each fixture, and every byte of the smallest: nothing faults (the
        // outlines, labels, forms and XMP readers all run on a document cut anywhere).
        emon.Port.Cells cut = emon.Port.NewCells();
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/labels-odd.pdf"), 1, cut) >= 1, "labels-odd");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/labels.pdf"), 11, cut) >= 1, "labels");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/outlines.pdf"), 11, cut) >= 1, "outlines");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/outline-cycles.pdf"), 7, cut) >= 1, "outline-cycles");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/forms.pdf"), 11, cut) >= 1, "forms");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/links.pdf"), 13, cut) >= 1, "links");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/stamps.pdf"), 11, cut) >= 1, "stamps");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/sigs.pdf"), 11, cut) >= 1, "sigs");
        emon.Testport.AssertThat(CgTruncations(emon.Testport.TestFile("pdf/catalog/meta.pdf"), 11, cut) >= 1, "meta");
    }
    [Xunit.Fact]
    public static void TestNoCorruptionOfAFixtureFaults() {
        // Copies with three bytes replaced, 150 of each: a wrong /Kids, /First, /Next, /Nums, /Kids
        // of a name tree, a broken tag in the XMP packet, an odd /Rect or /QuadPoints or /Ff.
