        emon.Testport.AssertThat(CgCorruptions(emon.Testport.TestFile("pdf/catalog/outline-cycles.pdf"), 150, 3, 3, cut, rng) >= 0, "cycles");
        emon.Testport.AssertThat(CgCorruptions(emon.Testport.TestFile("pdf/catalog/forms.pdf"), 150, 3, 4, cut, rng) >= 0, "forms");
        emon.Testport.AssertThat(CgCorruptions(emon.Testport.TestFile("pdf/catalog/links.pdf"), 150, 3, 5, cut, rng) >= 0, "links");
        emon.Testport.AssertThat(CgCorruptions(emon.Testport.TestFile("pdf/catalog/stamps.pdf"), 150, 3, 6, cut, rng) >= 0, "stamps");
        emon.Testport.AssertThat(CgCorruptions(emon.Testport.TestFile("pdf/catalog/sigs.pdf"), 150, 3, 7, cut, rng) >= 0, "sigs");
