    }
    internal static int CgAsync(byte[] bytes, int chunk, System.Text.StringBuilder t) {
        // Read `bytes` through an async source of `chunk`-byte chunks, re-running until an
        // attempt does not miss; the dump of that attempt goes to t. Answers that attempt's
        // verdict, or -2 after 40 rounds.
        emon.Port.Src @base = emon.Testport.SrcChunked(bytes, chunk, 0);
        int round = 0;
        int more = 1;
        int verdict = 0;
        while (more == 1) {
            emon.Port.Src v = emon.Testport.SrcView(@base);
            verdict = CgDump(v, t);
            if (Pdfsrc.PsMissed(v)) {
                emon.Testport.SrcCtl(@base, 0, round);
                round += 1;
                if (round > 40) {
                    more = 0;
                    verdict = -2;
                }
            } else {
                more = 0;
            }
        }
        return verdict;
    }
    internal static int CgAsyncRows(int chunk) {
        // Every row of test/pdf/catalog.txt through an async source of `chunk`-byte chunks: the
        // dump must be the golden. Answers the number of rows that were not.
        byte[] f = emon.Testport.TestFile("pdf/catalog.txt");
        int n = emon.Port.BlobLen(f);
        int pos = 0;
        int e = 0;
        int s0 = 0;
        int bad = 0;
        int rows = 0;
        while (pos < n) {
            e = CgNl(f, pos);
            if ((pos < e) && (emon.Port.BlobU8(f, pos) != 35)) {
                rows += 1;
                s0 = CgTab(f, pos, e);
                System.Text.StringBuilder t = emon.Testport.NewText();
                if (CgAsync(emon.Testport.TestFileSpan(f, pos, s0), chunk, t) != 0) {
                    bad += 1;
                }
            }
            pos = e + 1;
        }
        if (rows < 12) {
            return -1;
        }
        return bad;
    }
