        emon.Testport.AssertTextSpan(t, g, 0, emon.Port.BlobLen(g) - 1, "forms through 64-byte chunks", 1);
        System.Text.StringBuilder t2 = emon.Testport.NewText();
        byte[] g2 = emon.Testport.TestFile("pdf/catalog/meta-aes256.json");
        emon.Testport.AssertEq(CgAsync(emon.Testport.TestFile("pdf/catalog/meta-aes256.pdf"), 64, t2), 0, "read");
        emon.Testport.AssertTextSpan(t2, g2, 0, emon.Port.BlobLen(g2) - 1, "encrypted metadata through 64-byte chunks", 2);
        System.Text.StringBuilder t3 = emon.Testport.NewText();
