    }
    [Xunit.Fact]
    public static void TestRealFilesSayWhatQpdfAndPopplerSay() {
        // Row: path (relative to test/), then tab-separated facts taken from qpdf and poppler by
        // `kin/scripts/pdf-catalog-compare --write`: the bookmarks' count and digest, the labels'
        // digest, the links' count, URI count and digest, the PDF/UA part and the /Lang digest. The
        // digests are computed here from emon's arenas and must be the oracles' numbers.
        byte[] f = emon.Testport.TestFile("pdf/catalog-corpus.txt");
        int n = emon.Port.BlobLen(f);
        int pos = 0;
        int line = 0;
        int rows = 0;
        int e = 0;
        int s0 = 0;
        while (pos < n) {
            line += 1;
            e = CgNl(f, pos);
            if ((pos < e) && (emon.Port.BlobU8(f, pos) != 35)) {
                rows += 1;
                s0 = CgTab(f, pos, e);
                System.Text.StringBuilder t = emon.Testport.NewText();
                emon.Testport.AssertEqAt(CgLine(emon.Testport.TestFileSpan(f, pos, s0), 8, t), 0, "read", line);
                emon.Testport.AssertTextSpan(t, f, s0 + 1, e, "facts", line);
            }
            pos = e + 1;
        }
        emon.Testport.AssertThat(rows >= 100, "the real files were read");
    }
